import cors from 'cors';
import { createProxyMiddleware } from 'http-proxy-middleware';
import express, { type RequestHandler } from 'express';
import { createServer } from 'node:http';
import { expressMiddleware } from '@as-integrations/express5';
import { ApolloGateway, IntrospectAndCompose } from '@apollo/gateway';
import { ApolloServer } from '@apollo/server';
import { ApolloServerPluginDrainHttpServer } from '@apollo/server/plugin/drainHttpServer';
import { ApplicationInstance } from '@teambit/application';
import { GatewayContext, GatewayServer } from './gateway-server.js';


export type StartGatewayOptions = {
  /**
   * port the range.
   */
  port?: number;

  /**
   * X-Auth
   */
  platformHeaders?: Record<string, string>;
};

export class DefaultGateway implements GatewayServer {

  constructor(
    /**
     * name of the app.
     */
    readonly name = 'default-gateway',
  ) {}

  /**
   * run the symphony gateway.
   */
  /**
   * check which services expose a /graphql endpoint.
   */
  private async filterGraphqlServices(services: ApplicationInstance[]): Promise<ApplicationInstance[]> {
    const results = await Promise.all(
      services.map(async (service) => {
        const url = service.url || `http://localhost:${service.port}`;
        try {
          const res = await fetch(`${url}/graphql`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ query: '{ __typename }' }),
          });

          return res.ok;
        } catch {
          return false;
        }
      })
    );

    return services.filter((_, i) => results[i]);
  }

  async run(context: GatewayContext): Promise<ApplicationInstance> {
    const port = context.port || 3000;
    if (!context.services.length) return { port };
    const app = express();
    const httpServer = createServer(app);

    app.use(
      cors<cors.CorsRequest>({
        origin(origin, callback) {
          callback(null, true);
        },
        credentials: true,
      })
    );

    const graphqlServices = await this.filterGraphqlServices(context.services);

    if (graphqlServices.length) {
      const gateway = new ApolloGateway({
        supergraphSdl: new IntrospectAndCompose({
          subgraphs: graphqlServices.map((service) => {
            return {
              name: service.appName || '',
              url: service.url || `http://localhost:${service.port}/graphql`,
            };
          }),
        }),
      });

      const server = new ApolloServer({
        gateway,
        plugins: [ApolloServerPluginDrainHttpServer({ httpServer })],
      });

      await server.start();

      app.use(
        '/graphql',
        express.json(),
        expressMiddleware(server, {
          context: async ({ req }) => req,
        })
      );
    }

    // proxy all REST requests.
    context.services.forEach(({appName, port: servicePort, url }) => {
      const proxy = createProxyMiddleware({
        proxyTimeout: 3000,
        timeout: 3000,
        target: url || `http://localhost:${servicePort}`,
        changeOrigin: true,
        pathRewrite: { [`/${appName}/`]: '/' },
        onProxyRes: (proxyRes, _, res) => {
          if (proxyRes.statusCode === 404) {
            res.status(404);
            res.json({
              message: 'no resource found'
            });
          }
        }
      });
      app.use(`/${appName}`, proxy as unknown as RequestHandler);
    });

    app.get('/', (_, res) => {
      res.status(200);
      return res.json({
        message: 'ok',
      });
    });

    app.get('{*path}', (_, res) => {
      res.status(404);
      return res.json({
        message: 'no resource found',
      });
    });

    await new Promise<void>((resolve) => httpServer.listen({ port }, resolve));
    console.log(`🚀 API Gateway server ready at: http://localhost:${port}`);

    return {
      // url: `http://localhost:${port}`,
      port,
      // @ts-ignore until releasing bit
      stop: async () => {
        httpServer.closeAllConnections();
        httpServer.close();
      },
    };
  }


}